
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cam_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.484499671130785e+00, -3.417904142650310e+00, -3.324631537405469e+00, -3.195515623590377e+00, -3.019760861573600e+00, -2.786204483421568e+00, -2.486263801142820e+00, -2.119082444456356e+00, -1.697763887825352e+00, -1.250309463920821e+00, -8.096511995592980e-01, -5.279121587657866e-01, -4.482433195524524e-01, -3.600948309099086e-01, -2.407394417262671e-01, -1.259254700214487e-01, -5.773571948945098e-02, -3.593564382162000e-02, -2.184970629845661e-02, -1.466428948025301e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


